LIMITS_I = "Остаток лимитов на начало теста: ручки осмотра — 40 из 40, `ask-user` — 10 из 10 [AR-32]."


def insp_ctx(f, res, extra=""):
    return f + "\n\n" + INSPECTOR_HANDLES + "\n\n" + CHECKLIST + "\n\n" + res + ("\n\n" + extra if extra else "") + "\n\n" + LIMITS_I


