def insp_artifact(host, user_desc=None, hostname=None, ip=None):
    r = RECORDS[host]
    full = (r["full"] if not user_desc else ("По описанию пользователя: " + user_desc + ". " + r["full"])) + " Имя хоста: " + (hostname or r["name"]) + "."
    lines = ["Артефакт инспектора (`submit`) для " + (ip or r["ip"]) + " [AR-29]:", "",
             "- `full-desc`: " + full,
             "- `tags`: {" + ", ".join(r["tags"]) + "}",
             "- `tags-full-desc`:"]
    for t in r["tags"]:
        lines.append("  - %s — %s" % (t, r["tags_full"][t]))
    return "\n".join(lines)


def cafe_artifact(user_desc, ip="10.30.5.10"):
    lines = ["Артефакт инспектора (`submit`) для " + ip + " [AR-29]:", "",
             "- `full-desc`: По описанию пользователя: «" + user_desc + "». " + CAFE_FULL + " Имя хоста: cafe-05.",
             "- `tags`: {host, db/pg, docker}",
             "- `tags-full-desc`:"]
    for t in ("host", "db/pg", "docker"):
        lines.append("  - %s — %s" % (t, CAFE_TAGS_FULL[t]))
    return "\n".join(lines)


def others(hosts):
    rows = ["| server-name | tags | short-desc |", "|---|---|---|"]
    for h in hosts:
        r = RECORDS[h]
        rows.append("| %s | %s | %s |" % (r["name"], ", ".join(r["tags"]), r["short"]))
    return "Краткие описания уже добавленных серверов (вход куратора [UC-15]; удалённых серверов и «прошлых описаний» нет [UC-10]):\n\n" + "\n".join(rows)


CUR_TOOLS = "Тулзы куратора [AR-31]: `QA(question)` ≤ 5; `confirmation(short-desc, server-name)` ≤ 3 — карточка показывает ещё и `tags-short-desc` [UC-32], подтверждаются краткое описание и название [UC-21]; третья карточка — последняя: не подтверждена — добавление прерывается, сервер не добавляется; `deny(reason)` — терминальная: отказ пользователю, чат закрывается, сервер не добавляется; после 5 QA — только confirmation и deny [AR-43], [UC-35]. Лимиты куратор видит в контексте [AR-32]. Класс rule-based `[предл.]`: `QA` при конфликте → `conflict`, `confirmation` → `consistent`; `deny` класса в v0.2 не имеет [Q50]. Остаток на начало теста: QA 5, confirmation 3, если не сказано иное."
CUR_RB = "- Rule-based: `cur-conflict` — класс (тулза) совпадает с эталоном; при `conflict` — набор серверов совпадает с эталонным."
CUR_F = "- Rule-based: `cur-fields` `[предл.]` (X-FIELDS, [AR-29]) — `server-name` непустое, < 5 слов; `short-desc` < 50 слов; `tags-short-desc` — по каждому тегу из `tags` непустое, ≤ 30 слов; подстроки эталона — без учёта регистра (README, «Метрики»)."
CUR_J = "- LLM-judge: `judge-cur-question` — (1) язык понятен пользователю, без имён ручек, классов и тегов как идентификаторов; (2) суть донесена верно — спрошено, чем серверы отличаются; (3) указаны правильные документы — именно те серверы и описания, между которыми конфликт. Тест засчитан при всех трёх."
CUR_J_CAFE = CUR_J.replace("спрошено, чем серверы отличаются", "спрошено, чем новый сервер отличается от серверов кафе: адрес или место кафе").replace("именно те серверы и описания, между которыми конфликт", "серверы кафе, с которыми совпало описание; сервер офиса не упомянут как похожий")
CUR_J_SUM = """- LLM-judge: `judge-cur-summary` `[предл.]` — (1) `short-desc` — общие слова о сервере: роль и отличительные признаки из `full-desc` (описание пользователя и находки инспектора), по которым сервер узнают в запросах; точечные факты (порты, версии, пути) — не здесь; (2) в `short-desc` и `tags-short-desc` нет додуманных фактов — всё есть в артефакте инспектора или в ответах пользователя; (3) `tags-short-desc` по каждому тегу — ситуативное: для 1c — пользователи и ИБ, для db — СУБД и базы, для host — ресурсы и что в процессах; (4) `server-name` узнаваемо — роль или имя хоста из `full-desc`; без разговорных оборотов, личных имён и сведений о доступе. Тест засчитан при всех четырёх. В метриках v0.2 такого judge нет — требуется пунктом плана IN-2a (качество составленной информации) (README, открытые пункты)."""


def cur_ctx(artifact, others_text):
    return artifact + "\n\n" + others_text + "\n\n" + CUR_TOOLS


